function start(mode,opts={}){
 stop();
 const segments=getSections();
 if(!segments.length){
   setOpen(true);setStatus("Open a lesson post to start teaching. No article sections found.");
   return false;
 }
 setOpen(true);
 current=segments;
 at=Math.max(0,Math.min(segments.length-1,Number(opts.index)||0));
 active=true;updateReadButton(true);
 const runToken=token;
 function next(){
   if(runToken!==token||!active)return;
   if(at>=current.length){
     stop("Lesson complete. Choose a new lesson or select a passage.");return;
   }
   const item=current[at];
   highlight(item);
   setStatus((mode==="read"?"Reading":"Teaching")+" "+(at+1)+" / "+current.length+" · "+item.name);
   talk(guideText(item,mode),runToken,()=>{
     if(runToken!==token||!active)return;
     at++;
     timeoutId=setTimeout(next,260);
   });
 }
 next();
 return true;
}
function explainSelection(){
 const sel=window.getSelection?.(),live=clean(sel?.toString());
 const text=live||selectedCache.text;
 const root=article()||document.querySelector(".lwc-home");
 if(!text||text.length<3){setOpen(true);setStatus("Select a sentence or code fragment in the lesson first.");return;}
 const anchor=live?sel?.anchorNode:selectedCache.node;
 if(!root||!anchor||!root.contains(anchor)){
   setOpen(true);setStatus("Please select text inside the lesson.");return;
 }
 stop();setOpen(true);active=true;const myToken=token;
 const node=anchor.nodeType===1?anchor:anchor.parentElement;
 let el=node?.closest("pre,p,blockquote,li,h1,h2,h3,h4,h5,h6,table")||node;
 if(!root.contains(el))el=root;
 const kind=el?.closest("pre,code")?"code":"text";
 const entry={element:el,kind,name:"Selected passage",text:text.slice(0,1100)};
 highlight(entry);setStatus("Explaining selected passage · introductory guidance");
 talk(guideText(entry,"teach"),myToken,()=>stop("Selection explanation complete."));
}
function jump(step){
 if(!current.length){setStatus("Press Teach This Lesson first.");setOpen(true);return;}
 const mode="teach",pos=Math.max(0,Math.min(current.length-1,at+step));
 start(mode,{index:pos});
}
host.addEventListener("click",event=>{
 const button=event.target.closest("button[data-lwc-teach]");
 if(!button)return;
 switch(button.dataset.lwcTeach){
 case "teach":start("teach");break;
 case "read":start("read");break;
 case "selection":explainSelection();break;
 case "prev":jump(-1);break;
 case "next":jump(1);break;
 case "stop":stop("Stopped.");break;
 }
});
toggle.addEventListener("click",()=>setOpen(!prefs.open));
$("#lwcChamputerClose").addEventListener("click",()=>setOpen(false));
lang.addEventListener("change",()=>{prefs.lang=lang.value;save();if(active)stop("Language changed. Press Teach to restart.");});
rate.addEventListener("change",()=>{prefs.rate=Number(rate.value);save();});
document.addEventListener("selectionchange",()=>{
 const sel=window.getSelection?.(),txt=clean(sel?.toString());
 if(!txt||txt.length>3000||!sel.anchorNode)return;
 const root=article()||document.querySelector(".lwc-home");
 if(root?.contains(sel.anchorNode))selectedCache={text:txt,node:sel.anchorNode};
});
document.addEventListener("click",event=>{
 const speak=event.target.closest?.(".lwc-speak-content-button");
 if(speak){
   event.preventDefault();event.stopImmediatePropagation();
   if(active)stop("Stopped.");
   else start("read");
   return;
 }
 if(event.target.closest?.(".lwc-slideshow-float,[data-open-card-studio],a[href='#lwc-card-studio']"))
   {if(active)stop("Paused while another activity is open.");}
},true);
window.addEventListener("pagehide",()=>stop());
window.addEventListener("hashchange",()=>{if(location.hash==="#lwc-card-studio"&&active)stop("Paused while Card Studio is open.");});
document.addEventListener("visibilitychange",()=>{if(document.hidden&&active)stop("Paused because the tab is hidden.");});
document.addEventListener("keydown",event=>{if(event.key==="Escape"&&active){stop("Stopped.");}});
setOpen(false);
function announce(message,element,options={}){
 const text=clean(message).slice(0,2400);
 if(!text)return false;
 stop();
 const runToken=token;
 active=true;
 if(options.open!==false)setOpen(true);
 if(element?.isConnected)highlight({element,kind:"text",name:"Guided explanation",text});
 setStatus(String(options.status||"Champuter is explaining this example.").slice(0,160));
 talk(text,runToken,()=>{if(token===runToken)stop("Explanation finished.");});
 return true;
}
function pointTo(element,caption){
 if(!element?.isConnected)return false;
 stop();
 setOpen(true);
 highlight({element,kind:"text",name:"Highlighted section",text:""});
 setStatus(String(caption||"Look at the highlighted section.").slice(0,160));
 return true;
}
window.LWCChamputerBlog={start,stop,sections,explainSelection,announce,pointTo,openMenu:setOpen,getLanguage:()=>prefs.lang,getStatus:()=>({active,index:at,count:current.length,lang:prefs.lang})};
